"use strict";

CFG.domainFunction=CFG.domainFunction||"aora-v8-domain-api";
CFG.featureFunction=CFG.featureFunction||"aora-v8-feature-actions";
S.u=S.u||{
  flags:{},flagsLoaded:false,
  calendar:{mode:"month",cursor:null,selected:null,data:null,key:"",loading:false,error:""},
  schedule:{week:null,data:null,key:"",loading:false,error:"",warning:null},
  tasks:{data:[],selected:null,loading:false,error:"",managerData:null,managerLoading:false},
  update:{waiting:null},
  push:{busy:false}
};

function uFlag(key){return Boolean(S.u.flags?.[key]?.enabled)}
function uErrorMessage(error){return error?.data?.error?.message||error?.message||"Unbekannter Fehler"}
async function uCall(action,payload={},feature=false){
  if(!S.session?.token)throw new Error("Sitzung fehlt.");
  const envelope=await request(feature?CFG.featureFunction:CFG.domainFunction,{action,token:S.session.token,...payload});
  if(envelope?.error)throw Object.assign(new Error(envelope.error.message||"Aktion fehlgeschlagen."),{data:envelope});
  return envelope?.data;
}
function uDate(value=new Date()){return new Date(value).toISOString().slice(0,10)}
function uDateObj(text){return new Date(`${text}T12:00:00Z`)}
function uAdd(text,days){const date=uDateObj(text);date.setUTCDate(date.getUTCDate()+days);return uDate(date)}
function uStartWeek(text=uDate()){const date=uDateObj(text);const day=(date.getUTCDay()+6)%7;date.setUTCDate(date.getUTCDate()-day);return uDate(date)}
function uMonthStart(text=uDate()){return `${text.slice(0,7)}-01`}
function uMonthEnd(text){const date=uDateObj(uMonthStart(text));date.setUTCMonth(date.getUTCMonth()+1);date.setUTCDate(0);return uDate(date)}
function uMonthLabel(text){return new Intl.DateTimeFormat("de-DE",{month:"long",year:"numeric",timeZone:"UTC"}).format(uDateObj(text))}
function uDayLabel(text,short=false){return new Intl.DateTimeFormat("de-DE",short?{weekday:"short",day:"2-digit",month:"2-digit",timeZone:"UTC"}:{weekday:"long",day:"2-digit",month:"long",year:"numeric",timeZone:"UTC"}).format(uDateObj(text))}
function uHtml(value){return typeof esc==="function"?esc(value):String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[char]))}
function uBusy(){return'<div class="u-loading"><div><div class="u-spinner"></div><p>Lädt …</p></div></div>'}
function uEmpty(text){return`<div class="u-empty">${uHtml(text)}</div>`}
function uButton(label,action,data="",kind="secondary",disabled=false){return`<button class="u-btn ${kind}" data-u="${action}" ${data} ${disabled?"disabled":""}>${uHtml(label)}</button>`}
function uLocationName(idValue){return S.state?.locations?.find(item=>String(item.id)===String(idValue))?.name||idValue||""}
function uEmployeeName(idValue){return S.state?.employees?.find(item=>String(item.id)===String(idValue))?.name||idValue||"Offene Schicht"}
function uCurrentEmployee(){return S.state?.employees?.find(item=>String(item.id)===String(S.session?.subjectId))||S.state?.employees?.[0]}

async function uLoadFlags(){
  if(!S.session?.token)return;
  try{S.u.flags=await uCall("flags");S.u.flagsLoaded=true}catch(error){console.warn("Feature flags unavailable",error);S.u.flagsLoaded=false}
}
const uLegacyLoadState=loadState;
loadState=async function(...args){
  await uLegacyLoadState(...args);
  if(S.session?.token){await uLoadFlags();render()}
};

function uCalendarRange(){
  const cursor=S.u.calendar.cursor||uMonthStart(berlin().date);
  if(S.u.calendar.mode==="week"){const start=uStartWeek(cursor);return{from:start,to:uAdd(start,6)}}
  if(S.u.calendar.mode==="list")return{from:cursor,to:uAdd(cursor,31)};
  const first=uMonthStart(cursor),last=uMonthEnd(cursor);return{from:uAdd(uStartWeek(first),-0),to:uAdd(uStartWeek(last),6)};
}
async function uEnsureCalendar(force=false){
  if(!uFlag("calendar_v2"))return;
  const range=uCalendarRange(),key=`${range.from}:${range.to}:${S.session?.subjectId}`;
  if(!force&&S.u.calendar.key===key&&S.u.calendar.data)return;
  if(S.u.calendar.loading)return;
  S.u.calendar.loading=true;S.u.calendar.error="";render();
  try{S.u.calendar.data=await uCall("calendar",range);S.u.calendar.key=key;if(!S.u.calendar.selected)S.u.calendar.selected=berlin().date}
  catch(error){S.u.calendar.error=uErrorMessage(error)}finally{S.u.calendar.loading=false;render()}
}
function uCalendarEvents(date){const data=S.u.calendar.data||{};return{
  shifts:(data.shifts||[]).filter(item=>item.date===date),
  entries:(data.timeEntries||[]).filter(item=>item.date===date||String(item.startTime||"").slice(0,10)===date),
  tasks:(data.tasks||[]).filter(item=>String(item.instance_date||item.scheduled_for||"").slice(0,10)===date),
  leave:(data.leaveRequests||[]).filter(item=>date>=String(item.starts_on||item.payload?.start||"")&&date<=String(item.ends_on||item.payload?.end||"")),
  notes:(data.notifications||[]).filter(item=>String(item.created_at||"").slice(0,10)===date)
}}
function uDayCard(date,outside=false){const events=uCalendarEvents(date);const selected=S.u.calendar.selected===date;const today=berlin().date===date;const lines=[];events.shifts.slice(0,2).forEach(shift=>lines.push(`<div class="u-day-line">${uHtml(shift.start)}–${uHtml(shift.end)} ${uHtml(uLocationName(shift.locationId))}</div>`));events.tasks.slice(0,1).forEach(task=>lines.push(`<div class="u-day-line">✓ ${uHtml(task.task_templates?.title||"Aufgabe")}</div>`));return`<button class="u-day ${outside?"outside":""} ${selected?"selected":""} ${today?"today":""}" data-u="calendar-day" data-date="${date}"><span class="u-day-number">${Number(date.slice(8,10))}</span><span class="u-indicators">${events.shifts.map(item=>`<i class="u-indicator ${item.status==="open"?"open":item.status==="pending_confirmation"?"pending":""}"></i>`).join("")}${events.tasks.length?'<i class="u-indicator task"></i>':""}${events.leave.length?'<i class="u-indicator leave"></i>':""}</span><span class="u-day-lines">${lines.join("")}</span></button>`}
function uShiftActions(shift){const own=String(shift.employeeId)===String(S.session?.subjectId);const open=!shift.employeeId&&shift.status==="open";return`<div class="u-actions">${own&&["published","pending_confirmation"].includes(shift.status)?uButton("Bestätigen","shift-response",`data-id="${shift.id}" data-response="confirmed"`,""):""}${own?uButton("Ablehnen","shift-response",`data-id="${shift.id}" data-response="rejected"`,"danger"):""}${own?uButton("Tausch anfragen","shift-swap",`data-id="${shift.id}"`):""}${open?uButton("Reservieren","open-shift-claim",`data-id="${shift.id}"`,""):""}</div>`}
function uCalendarDetail(date){const events=uCalendarEvents(date);return`<section class="u-day-detail"><div class="u-toolbar"><div><div class="caps muted">Tagesdetails</div><h2>${uHtml(uDayLabel(date))}</h2></div>${uButton("Verfügbarkeit setzen","availability",`data-date="${date}"`)}</div><div class="u-detail-grid">
  <div><h3>Schichten</h3>${events.shifts.map(shift=>`<article class="u-item-card"><h3>${uHtml(shift.start)}–${uHtml(shift.end)} · ${uHtml(uLocationName(shift.locationId))}</h3><p>Status: ${uHtml(shift.status)} · Pause ${Number(shift.breakMinutes||0)} Min.</p>${uShiftActions(shift)}</article>`).join("")||uEmpty("Keine Schicht.")}</div>
  <div><h3>Aufgaben</h3>${events.tasks.map(task=>`<article class="u-item-card"><h3>${uHtml(task.task_templates?.title||"Aufgabe")}</h3><p>${uHtml(task.status)} · fällig ${uHtml(String(task.due_at||"").slice(11,16))}</p>${uButton("Öffnen","task-open",`data-id="${task.id}"`,"")}</article>`).join("")||uEmpty("Keine Aufgabe.")}</div>
  <div><h3>Zeiten & Abwesenheit</h3>${events.entries.map(entry=>`<article class="u-item-card"><h3>${uHtml(String(entry.startTime||"").slice(11,16))}–${uHtml(String(entry.endTime||"läuft").slice(11,16))}</h3><p>${Number(entry.durationMinutes||0)} Minuten · ${uHtml(entry.status)}</p></article>`).join("")}${events.leave.map(item=>`<article class="u-item-card"><h3>Abwesenheit</h3><p>${uHtml(item.status)}</p></article>`).join("")||(!events.entries.length&&!events.leave.length?uEmpty("Keine Einträge."):"")}</div>
</div></section>`}
function uRenderMonth(){const cursor=S.u.calendar.cursor||uMonthStart(berlin().date),first=uMonthStart(cursor),gridStart=uStartWeek(first);const days=[];for(let i=0;i<42;i++){const date=uAdd(gridStart,i);days.push(uDayCard(date,date.slice(0,7)!==first.slice(0,7)))}return`<div class="u-month-grid">${["Mo","Di","Mi","Do","Fr","Sa","So"].map(day=>`<div class="u-weekday">${day}</div>`).join("")}${days.join("")}</div>${uCalendarDetail(S.u.calendar.selected||berlin().date)}`}
function uRenderWeek(){const start=uStartWeek(S.u.calendar.cursor||berlin().date);return`<div class="u-detail-grid">${Array.from({length:7},(_,index)=>{const date=uAdd(start,index),events=uCalendarEvents(date);return`<section class="u-day-detail"><h3>${uHtml(uDayLabel(date,true))}</h3>${events.shifts.map(shift=>`<article class="u-item-card"><strong>${uHtml(shift.start)}–${uHtml(shift.end)}</strong><p>${uHtml(uLocationName(shift.locationId))}</p>${uShiftActions(shift)}</article>`).join("")}${events.tasks.map(task=>`<article class="u-item-card"><strong>${uHtml(task.task_templates?.title||"Aufgabe")}</strong>${uButton("Öffnen","task-open",`data-id="${task.id}"`)}</article>`).join("")||uEmpty("Frei")}</section>`}).join("")}</div>`}
function uRenderList(){const range=uCalendarRange();const rows=[];for(let date=range.from;date<=range.to;date=uAdd(date,1)){const events=uCalendarEvents(date);if(!events.shifts.length&&!events.tasks.length&&!events.leave.length)continue;rows.push(`<div class="u-list-date">${uHtml(uDayLabel(date))}</div>${events.shifts.map(shift=>`<article class="u-item-card"><h3>${uHtml(shift.start)}–${uHtml(shift.end)} · ${uHtml(uLocationName(shift.locationId))}</h3><p>${uHtml(shift.status)}</p>${uShiftActions(shift)}</article>`).join("")}${events.tasks.map(task=>`<article class="u-item-card"><h3>${uHtml(task.task_templates?.title||"Aufgabe")}</h3>${uButton("Öffnen","task-open",`data-id="${task.id}"`)}</article>`).join("")}`)}return`<div class="u-list-view">${rows.join("")||uEmpty("Keine Einträge im gewählten Zeitraum.")}</div>`}
function uCalendarPage(){queueMicrotask(()=>uEnsureCalendar());if(S.u.calendar.loading&&!S.u.calendar.data)return uBusy();if(S.u.calendar.error)return`<div class="u-warning-panel">${uHtml(S.u.calendar.error)} ${uButton("Erneut laden","calendar-reload")}</div>`;const cursor=S.u.calendar.cursor||uMonthStart(berlin().date);return`<section class="u-calendar-shell"><div class="u-toolbar"><div><div class="caps muted">Dienstplan & Aufgaben</div><h1>${uHtml(S.u.calendar.mode==="month"?uMonthLabel(cursor):uDayLabel(uCalendarRange().from))}</h1></div><div class="u-toolbar-group"><button class="u-icon-btn" data-u="calendar-prev">‹</button><button class="u-btn secondary" data-u="calendar-today">Heute</button><button class="u-icon-btn" data-u="calendar-next">›</button><div class="u-segmented">${[["month","Monat"],["week","Woche"],["list","Liste"]].map(([key,label])=>`<button data-u="calendar-mode" data-mode="${key}" class="${S.u.calendar.mode===key?"active":""}">${label}</button>`).join("")}</div></div></div>${S.u.calendar.mode==="month"?uRenderMonth():S.u.calendar.mode==="week"?uRenderWeek():uRenderList()}</section>`}

function uScheduleRange(){const start=S.u.schedule.week||uStartWeek(berlin().date);return{from:start,to:uAdd(start,6)}}
async function uEnsureSchedule(force=false){if(!uFlag("schedule_board_v2")||!S.locationId)return;const range=uScheduleRange(),key=`${S.locationId}:${range.from}:${range.to}`;if(!force&&S.u.schedule.key===key&&S.u.schedule.data)return;if(S.u.schedule.loading)return;S.u.schedule.loading=true;S.u.schedule.error="";render();try{S.u.schedule.data=await uCall("scheduleBoard",{locationId:S.locationId,...range});S.u.schedule.key=key}catch(error){S.u.schedule.error=uErrorMessage(error)}finally{S.u.schedule.loading=false;render()}}
function uScheduleCard(shift){const warning=S.u.schedule.warning?.shiftId===shift.id;return`<button class="u-shift-card ${shift.status==="open"?"open":""} ${warning?"warning":""}" draggable="true" data-shift-id="${shift.id}" data-u="shift-edit"><strong>${uHtml(shift.start)}–${uHtml(shift.end)}</strong><small>${uHtml(shift.status)} · ${Number(shift.breakMinutes||0)} Min.</small></button>`}
function uSchedulePage(){queueMicrotask(()=>uEnsureSchedule());if(S.u.schedule.loading&&!S.u.schedule.data)return uBusy();if(S.u.schedule.error)return`<div class="u-warning-panel">${uHtml(S.u.schedule.error)} ${uButton("Erneut laden","schedule-reload")}</div>`;const data=S.u.schedule.data;if(!data)return uBusy();const range=uScheduleRange(),days=Array.from({length:7},(_,i)=>uAdd(range.from,i));const employees=data.employees||[];const shifts=data.shifts||[];const planned=shifts.reduce((sum,item)=>sum+Math.max(0,mins(item.start,item.end,item.breakMinutes||0)),0);const open=shifts.filter(item=>item.status==="open"&&!item.employeeId).length;const pending=(data.shiftRequests||[]).filter(item=>item.status==="pending").length;return`<section class="u-schedule-shell"><div class="u-toolbar"><div><div class="caps muted">Weekly Planning Board</div><h1>${uHtml(uDayLabel(range.from,true))} – ${uHtml(uDayLabel(range.to,true))}</h1></div><div class="u-toolbar-group"><button class="u-icon-btn" data-u="schedule-prev">‹</button><button class="u-btn secondary" data-u="schedule-today">Diese Woche</button><button class="u-icon-btn" data-u="schedule-next">›</button>${uButton("Woche kopieren","schedule-copy")}${uButton("Veröffentlichen","schedule-publish",``,"")}${uButton("Neue Schicht","shift-new",``,"")}${uButton("Serienschicht","series-new")}</div></div><div class="u-board-summary"><div class="u-summary-card"><strong>${fm(planned)}</strong><small>Geplante Stunden</small></div><div class="u-summary-card"><strong>${open}</strong><small>Offene Schichten</small></div><div class="u-summary-card"><strong>${pending}</strong><small>Anfragen</small></div><div class="u-summary-card"><strong>${employees.length}</strong><small>Mitarbeiter</small></div></div>${S.u.schedule.warning?`<div class="u-warning-panel">${uHtml(S.u.schedule.warning.message)}</div>`:""}<div class="u-schedule-board"><div class="u-schedule-grid"><div class="u-grid-cell u-grid-head u-employee-cell">Mitarbeiter</div>${days.map(day=>`<div class="u-grid-cell u-grid-head">${uHtml(uDayLabel(day,true))}</div>`).join("")}${employees.map(employee=>`<div class="u-grid-cell u-employee-cell"><strong>${uHtml(employee.name)}</strong><small>${uHtml(employee.role_title||employee.role||"")}</small></div>${days.map(day=>`<div class="u-grid-cell u-drop-target" data-u-drop-employee="${employee.id}" data-u-drop-date="${day}">${shifts.filter(item=>item.employeeId===employee.id&&item.date===day).map(uScheduleCard).join("")}</div>`).join("")}`).join("")}<div class="u-grid-cell u-employee-cell"><strong>Offene Schichten</strong><small>Reservierbar</small></div>${days.map(day=>`<div class="u-grid-cell u-drop-target" data-u-drop-employee="" data-u-drop-date="${day}">${shifts.filter(item=>!item.employeeId&&item.date===day).map(uScheduleCard).join("")}</div>`).join("")}</div></div><section class="u-day-detail"><h2>Offene Anfragen</h2>${(data.shiftRequests||[]).filter(item=>item.status==="pending").map(item=>`<article class="u-item-card"><h3>${uHtml(uEmployeeName(item.employee_id))}</h3><p>${uHtml(item.request_type)} · ${uHtml(item.reason||"Ohne Begründung")}</p><div class="u-actions">${uButton("Annehmen","request-decision",`data-id="${item.id}" data-decision="approved"`,"")}${uButton("Ablehnen","request-decision",`data-id="${item.id}" data-decision="rejected"`,"danger")}</div></article>`).join("")||uEmpty("Keine offenen Anfragen.")}</section></section>`}

async function uEnsureEmployeeTasks(force=false){if(!uFlag("task_automation"))return;if(S.u.tasks.loading)return;if(!force&&S.u.tasks.data?.length)return;S.u.tasks.loading=true;S.u.tasks.error="";render();const from=uAdd(berlin().date,-14),to=uAdd(berlin().date,45);try{S.u.tasks.data=await uCall("tasks",{from,to});if(!S.u.tasks.selected&&S.u.tasks.data.length)S.u.tasks.selected=S.u.tasks.data[0].id}catch(error){S.u.tasks.error=uErrorMessage(error)}finally{S.u.tasks.loading=false;render()}}
function uTaskTitle(task){return task.task_templates?.title||"Aufgabe"}
function uTaskAnswer(task,item){return(task.task_answers||[]).find(answer=>answer.template_item_id===item.id)}
function uTaskField(task,item){const answer=uTaskAnswer(task,item),value=answer?.value??"";if(item.answer_type==="checkbox")return`<input type="checkbox" data-u-task-input data-task="${task.id}" data-item="${item.id}" data-version="${answer?.version||0}" ${value===true?"checked":""}>`;if(item.answer_type==="number")return`<input type="number" data-u-task-input data-task="${task.id}" data-item="${item.id}" data-version="${answer?.version||0}" value="${uHtml(value)}" ${item.min_value!=null?`min="${item.min_value}"`:""} ${item.max_value!=null?`max="${item.max_value}"`:""}>`;if(item.answer_type==="select")return`<select data-u-task-input data-task="${task.id}" data-item="${item.id}" data-version="${answer?.version||0}"><option value="">Bitte wählen</option>${(item.options||[]).map(option=>`<option value="${uHtml(option)}" ${String(value)===String(option)?"selected":""}>${uHtml(option)}</option>`).join("")}</select>`;if(item.answer_type==="photo")return`<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" data-u-task-file data-task="${task.id}" data-item="${item.id}"><div class="u-upload-status">${(task.task_evidence||[]).some(file=>file.template_item_id===item.id)?"Datei hochgeladen":"Noch keine Datei"}</div>`;return`<textarea rows="3" data-u-task-input data-task="${task.id}" data-item="${item.id}" data-version="${answer?.version||0}">${uHtml(value)}</textarea>`}
function uTaskDetail(task){if(!task)return uEmpty("Aufgabe auswählen.");const items=task.task_templates?.task_template_items||[];return`<section><div class="u-toolbar"><div><div class="caps muted">${uHtml(task.task_templates?.category||"Aufgabe")}</div><h2>${uHtml(uTaskTitle(task))}</h2><p>${uHtml(task.status)} · fällig ${uHtml(String(task.due_at||"").replace("T"," ").slice(0,16))}</p></div></div>${items.map(item=>`<div class="u-task-item"><label class="${item.required?"u-required":""}">${uHtml(item.label)}</label>${uTaskField(task,item)}</div>`).join("")||uEmpty("Keine Elemente.")}<div class="u-actions">${!task.task_assignments?.length?uButton("Aufgabe übernehmen","task-claim",`data-id="${task.id}"`,""):""}${uButton("Aufgabe abschließen","task-submit",`data-id="${task.id}"`,"")}</div></section>`}
function uEmployeeTasksPage(){queueMicrotask(()=>uEnsureEmployeeTasks());if(S.u.tasks.loading&&!S.u.tasks.data.length)return uBusy();if(S.u.tasks.error)return`<div class="u-warning-panel">${uHtml(S.u.tasks.error)} ${uButton("Erneut laden","tasks-reload")}</div>`;const selected=S.u.tasks.data.find(item=>item.id===S.u.tasks.selected);return`<section class="u-task-shell"><div class="employee-page-title"><div><div class="caps muted">Aufgaben</div><h1>Meine Aufgaben</h1></div><span class="u-sync-chip">${S.u.tasks.data.filter(item=>!["completed","waived","cancelled"].includes(item.status)).length} offen</span></div><div class="u-task-layout"><div class="u-task-list">${S.u.tasks.data.map(task=>`<button class="u-task-row ${task.id===S.u.tasks.selected?"active":""}" data-u="task-select" data-id="${task.id}"><strong>${uHtml(uTaskTitle(task))}</strong><small>${uHtml(task.status)} · ${uHtml(String(task.due_at||"").slice(0,16).replace("T"," "))}</small></button>`).join("")||uEmpty("Keine Aufgaben.")}</div><div class="u-task-detail">${uTaskDetail(selected)}</div></div></section>`}

async function uEnsureManagerTasks(force=false){if(!uFlag("task_automation")||!S.locationId)return;if(S.u.tasks.managerLoading)return;if(!force&&S.u.tasks.managerData?.locationId===S.locationId)return;S.u.tasks.managerLoading=true;render();try{const from=uAdd(berlin().date,-14),to=uAdd(berlin().date,45);const[templates,rules,tasks]=await Promise.all([uCall("taskTemplates",{locationId:S.locationId}),uCall("taskRules",{locationId:S.locationId}),uCall("tasks",{locationId:S.locationId,from,to})]);S.u.tasks.managerData={locationId:S.locationId,templates,rules,tasks}}catch(error){S.u.tasks.error=uErrorMessage(error)}finally{S.u.tasks.managerLoading=false;render()}}
function uManagerTasksPage(){queueMicrotask(()=>uEnsureManagerTasks());if(S.u.tasks.managerLoading&&!S.u.tasks.managerData)return uBusy();const data=S.u.tasks.managerData||{templates:[],rules:[],tasks:[]};return`<section class="u-task-shell"><div class="u-toolbar"><div><div class="caps muted">Aufgaben & Checklisten</div><h1>Task Automation</h1></div><div class="u-toolbar-group">${uButton("Template erstellen","template-new",``,"")}${uButton("Automatisierung","rule-new")}${uButton("Aufgabe zuweisen","manual-task-new")}</div></div><div class="u-board-summary"><div class="u-summary-card"><strong>${data.templates.length}</strong><small>Templates</small></div><div class="u-summary-card"><strong>${data.rules.filter(item=>item.active).length}</strong><small>Aktive Regeln</small></div><div class="u-summary-card"><strong>${data.tasks.filter(item=>!["completed","waived","cancelled"].includes(item.status)).length}</strong><small>Offene Tasks</small></div><div class="u-summary-card"><strong>${data.tasks.filter(item=>item.status==="submitted").length}</strong><small>Zur Prüfung</small></div></div><h2>Vorlagen</h2><div class="u-template-grid">${data.templates.map(template=>`<article class="u-item-card"><h3>${uHtml(template.title)}</h3><p>${uHtml(template.category)} · ${template.task_template_items?.length||0} Elemente · ${uHtml(template.clockout_policy)}</p>${uButton("Bearbeiten","template-edit",`data-id="${template.id}"`)}</article>`).join("")||uEmpty("Noch keine Vorlage.")}</div><h2>Automatisierungen</h2><div class="u-template-grid">${data.rules.map(rule=>`<article class="u-item-card"><h3>${uHtml(rule.task_templates?.title||rule.id)}</h3><p>${uHtml(rule.trigger_type)} · ${uHtml(rule.assignment_strategy)} · ${uHtml(rule.clockout_policy)}</p><span class="pill">${rule.active?"Aktiv":"Pausiert"}</span></article>`).join("")||uEmpty("Keine Automatisierung.")}</div><h2>Aktuelle Aufgaben</h2><div class="u-template-grid">${data.tasks.map(task=>`<article class="u-item-card"><h3>${uHtml(uTaskTitle(task))}</h3><p>${uHtml(task.status)} · ${uHtml(uEmployeeName(task.task_assignments?.[0]?.employee_id))}</p>${task.status==="submitted"?`<div class="u-actions">${uButton("Freigeben","task-review",`data-id="${task.id}" data-decision="completed"`,"")}${uButton("Zurückweisen","task-review",`data-id="${task.id}" data-decision="rejected"`,"danger")}</div>`:""}</article>`).join("")||uEmpty("Keine Aufgaben.")}</div></section>`}

const uLegacyEmployeeView=employeeView;
employeeView=function(employee,view){if(view==="calendar"&&uFlag("calendar_v2"))return uCalendarPage();if(view==="tasks"&&uFlag("task_automation"))return uEmployeeTasksPage();const result=uLegacyEmployeeView(employee,view);if(view==="more"&&uFlag("task_automation"))return result.replace('<button class="btn outline" style="width:100%;margin-top:14px" data-a="logout">',`${uButton("Meine Aufgaben","employee-tasks",``,"")}<button class="btn outline" style="width:100%;margin-top:14px" data-a="logout">`);return result};
const uLegacyRenderEmployee=renderEmployee;
renderEmployee=function(){uLegacyRenderEmployee();if(!uFlag("task_automation"))return;const nav=document.querySelector(".employee-bottom");if(nav&&!nav.querySelector('[data-view="tasks"]')){const more=nav.querySelector('[data-view="more"]');const button=document.createElement("button");button.dataset.u="employee-tasks";button.dataset.view="tasks";button.className=S.employeeView==="tasks"?"active":"";button.innerHTML=`${I.check||I.news}<span>Aufgaben</span>`;nav.insertBefore(button,more)}};
try{if(!managerNav.some(item=>item[0]==="tasks"))managerNav.splice(Math.max(0,managerNav.length-2),0,["tasks","Aufgaben",I.check||I.news]);if(!ownerNav.some(item=>item[0]==="tasks"))ownerNav.splice(Math.max(0,ownerNav.length-2),0,["tasks","Aufgaben",I.check||I.news])}catch{}
const uLegacyAdminView=adminView;
adminView=function(){if(S.adminView==="schedule"&&uFlag("schedule_board_v2"))return uSchedulePage();if(S.adminView==="tasks"&&uFlag("task_automation"))return uManagerTasksPage();return uLegacyAdminView()};
const uLegacyAdminTitle=adminTitle;
adminTitle=function(){if(S.adminView==="tasks")return"Aufgaben";return uLegacyAdminTitle()};

function uDialog(title,body,onSubmit){document.querySelector(".u-dialog-backdrop")?.remove();const backdrop=document.createElement("div");backdrop.className="u-dialog-backdrop";backdrop.innerHTML=`<form class="u-dialog"><h2>${uHtml(title)}</h2>${body}<div class="u-dialog-footer"><button type="button" class="u-btn secondary" data-u="dialog-close">Abbrechen</button><button class="u-btn" type="submit">Speichern</button></div></form>`;document.body.appendChild(backdrop);backdrop.querySelector("form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('[type="submit"]');button.disabled=true;try{await onSubmit(new FormData(form));backdrop.remove()}catch(error){toast(uErrorMessage(error),"error")}finally{button.disabled=false}})}
function uAsk(title,label,initial=""){return new Promise(resolve=>uDialog(title,`<div class="u-field"><label>${uHtml(label)}</label><textarea name="value" rows="4">${uHtml(initial)}</textarea></div>`,async form=>resolve(String(form.get("value")||""))))}
function uShiftDialog(shift=null){const data=S.u.schedule.data||{employees:[]};const date=shift?.date||uScheduleRange().from;uDialog(shift?"Schicht bearbeiten":"Neue Schicht",`<div class="u-form-grid"><div class="u-field"><label>Datum</label><input name="date" type="date" value="${date}" required></div><div class="u-field"><label>Mitarbeiter</label><select name="employeeId"><option value="">Offene Schicht</option>${data.employees.map(employee=>`<option value="${employee.id}" ${shift?.employeeId===employee.id?"selected":""}>${uHtml(employee.name)}</option>`).join("")}</select></div><div class="u-field"><label>Beginn</label><input name="start" type="time" value="${shift?.start||"08:00"}" required></div><div class="u-field"><label>Ende</label><input name="end" type="time" value="${shift?.end||"16:00"}" required></div><div class="u-field"><label>Pause (Min.)</label><input name="breakMinutes" type="number" min="0" value="${shift?.breakMinutes||30}"></div><div class="u-field"><label>Status</label><select name="status"><option value="draft">Entwurf</option><option value="published">Veröffentlicht</option><option value="open">Offen</option></select></div></div>${shift?`<div class="u-actions">${uButton("Schicht löschen","shift-delete",`data-id="${shift.id}"`,"danger")}</div>`:""}`,async form=>{const payload={id:shift?.id,locationId:S.locationId,date:String(form.get("date")),employeeId:String(form.get("employeeId")||"")||null,start:String(form.get("start")),end:String(form.get("end")),breakMinutes:Number(form.get("breakMinutes")||0),status:String(form.get("status")||"draft"),version:shift?.version||1};try{await uCall(shift?"updateShift":"createShift",{shift:payload,expectedVersion:shift?.version});S.u.schedule.warning=null;await uEnsureSchedule(true)}catch(error){if(error?.data?.error?.details){S.u.schedule.warning={shiftId:shift?.id,message:uErrorMessage(error)};render()}throw error}})}
function uSeriesDialog(){uDialog("Serienschicht",`<div class="u-form-grid"><div class="u-field"><label>Von</label><input name="startsOn" type="date" value="${uScheduleRange().from}" required></div><div class="u-field"><label>Bis</label><input name="endsOn" type="date" value="${uAdd(uScheduleRange().from,28)}" required></div><div class="u-field"><label>Rhythmus</label><select name="recurrence"><option value="weekly">Wöchentlich</option><option value="biweekly">Alle 2 Wochen</option><option value="daily">Täglich</option></select></div><div class="u-field"><label>Mitarbeiter</label><select name="employeeId"><option value="">Offen</option>${(S.u.schedule.data?.employees||[]).map(employee=>`<option value="${employee.id}">${uHtml(employee.name)}</option>`).join("")}</select></div><div class="u-field"><label>Beginn</label><input name="start" type="time" value="08:00"></div><div class="u-field"><label>Ende</label><input name="end" type="time" value="16:00"></div><div class="u-field"><label>Pause</label><input name="breakMinutes" type="number" value="30"></div></div>`,async form=>{await uCall("createShiftSeries",{series:{locationId:S.locationId,startsOn:String(form.get("startsOn")),endsOn:String(form.get("endsOn")),recurrence:String(form.get("recurrence")),employeeId:String(form.get("employeeId")||"")||null,start:String(form.get("start")),end:String(form.get("end")),breakMinutes:Number(form.get("breakMinutes")||0)}});await uEnsureSchedule(true)})}
function uTemplateDialog(template=null){const items=template?.task_template_items||[{label:"Aufgabe erledigt?",answer_type:"checkbox",required:true}];uDialog(template?"Template bearbeiten":"Template erstellen",`<div class="u-form-grid"><div class="u-field full"><label>Titel</label><input name="title" value="${uHtml(template?.title||"")}" required></div><div class="u-field"><label>Kategorie</label><select name="category">${["opening","closing","cleaning","inventory","safety","quality","maintenance","custom"].map(value=>`<option ${template?.category===value?"selected":""}>${value}</option>`).join("")}</select></div><div class="u-field"><label>Clock-out Policy</label><select name="policy">${["WARN_ONLY","MANAGER_OVERRIDE","STRICT_BLOCK"].map(value=>`<option ${template?.clockout_policy===value?"selected":""}>${value}</option>`).join("")}</select></div><div class="u-field full"><label>Beschreibung</label><textarea name="description">${uHtml(template?.description||"")}</textarea></div><div class="u-field full"><label>Items (eine Zeile: Typ|Pflicht|Label)</label><textarea name="items" rows="8">${items.map(item=>`${item.answer_type||"checkbox"}|${item.required?"required":"optional"}|${item.label}`).join("\n")}</textarea></div><label class="u-field full"><span>Review erforderlich</span><input name="review" type="checkbox" ${template?.review_required?"checked":""}></label></div>`,async form=>{const parsed=String(form.get("items")||"").split(/\n+/).map((line,index)=>{const[type,required,...label]=line.split("|");return{id:`item_${index+1}`,type:(type||"checkbox").trim(),required:(required||"").trim()==="required",label:label.join("|").trim()}}).filter(item=>item.label);await uCall("saveTaskTemplate",{template:{id:template?.id,locationId:S.locationId,title:String(form.get("title")),description:String(form.get("description")||""),category:String(form.get("category")),clockoutPolicy:String(form.get("policy")),reviewRequired:Boolean(form.get("review")),version:Number(template?.version||1)+(template?1:0),items:parsed}});await uEnsureManagerTasks(true)})}
function uRuleDialog(){const templates=S.u.tasks.managerData?.templates||[];uDialog("Automatisierung erstellen",`<div class="u-form-grid"><div class="u-field"><label>Template</label><select name="templateId">${templates.map(item=>`<option value="${item.id}">${uHtml(item.title)}</option>`).join("")}</select></div><div class="u-field"><label>Trigger</label><select name="triggerType"><option value="fixed_time">Feste Uhrzeit</option><option value="shift_start">Schichtbeginn</option><option value="shift_end">Schichtende</option><option value="before_shift_end">Vor Schichtende</option><option value="after_shift_start">Nach Schichtbeginn</option><option value="location_open">Ladenöffnung</option><option value="location_close">Ladenschluss</option></select></div><div class="u-field"><label>Uhrzeit</label><input name="time" type="time" value="16:00"></div><div class="u-field"><label>Zuweisung</label><select name="strategy"><option value="all_on_shift">Alle im Dienst</option><option value="one_on_shift">Eine Person im Dienst</option><option value="shift_leader">Schichtleitung</option><option value="specific_employee">Bestimmter Mitarbeiter</option><option value="specific_role">Bestimmte Rolle</option><option value="first_claim">First Claim</option><option value="round_robin">Round Robin</option></select></div><div class="u-field"><label>Deadline Offset (Min.)</label><input name="offset" type="number" value="30"></div><div class="u-field"><label>Clock-out Policy</label><select name="policy"><option>WARN_ONLY</option><option selected>MANAGER_OVERRIDE</option><option>STRICT_BLOCK</option></select></div></div>`,async form=>{await uCall("saveTaskRule",{rule:{locationId:S.locationId,templateId:String(form.get("templateId")),triggerType:String(form.get("triggerType")),triggerConfig:{time:String(form.get("time"))},assignmentStrategy:String(form.get("strategy")),assignmentConfig:{},dueOffsetMinutes:Number(form.get("offset")||0),clockoutPolicy:String(form.get("policy")),active:true,version:1}});await uEnsureManagerTasks(true)})}
function uManualTaskDialog(){const data=S.u.tasks.managerData||{templates:[]};uDialog("Aufgabe zuweisen",`<div class="u-form-grid"><div class="u-field"><label>Template</label><select name="templateId">${data.templates.map(item=>`<option value="${item.id}">${uHtml(item.title)}</option>`).join("")}</select></div><div class="u-field"><label>Mitarbeiter</label><select name="employeeId"><option value="">Offen / First Claim</option>${(S.u.schedule.data?.employees||S.state.employees.filter(item=>item.locationId===S.locationId)).map(item=>`<option value="${item.id}">${uHtml(item.name)}</option>`).join("")}</select></div><div class="u-field"><label>Datum</label><input name="date" type="date" value="${berlin().date}"></div><div class="u-field"><label>Fällig</label><input name="due" type="datetime-local" value="${berlin().date}T18:00"></div></div>`,async form=>{const employee=String(form.get("employeeId")||"");await uCall("createManualTask",{locationId:S.locationId,templateId:String(form.get("templateId")),employeeIds:employee?[employee]:[],date:String(form.get("date")),dueAt:new Date(String(form.get("due"))).toISOString()},true);await uEnsureManagerTasks(true)})}

async function uSaveTaskInput(element){const taskId=element.dataset.task,itemId=element.dataset.item,version=Number(element.dataset.version||0);let value;if(element.type==="checkbox")value=element.checked;else value=element.value;const result=await uCall("saveTaskAnswer",{taskId,itemId,value,expectedVersion:version});element.dataset.version=String(result.version);toast("Antwort gespeichert.","success")}
async function uUploadTaskFile(input){const file=input.files?.[0];if(!file)return;const taskId=input.dataset.task,itemId=input.dataset.item;const extension=(file.name.split(".").pop()||"bin").toLowerCase();const signed=await uCall("evidenceUpload",{taskId,itemId,mimeType:file.type,fileSize:file.size,extension});const upload=await fetch(signed.signedUrl,{method:"PUT",headers:{"Content-Type":file.type},body:file});if(!upload.ok)throw new Error(`Upload HTTP ${upload.status}`);const digest=await crypto.subtle.digest("SHA-256",await file.arrayBuffer());const sha=[...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,"0")).join("");await uCall("confirmEvidence",{taskId,itemId,path:signed.path,mimeType:file.type,fileSize:file.size,sha256:sha,capturedAt:new Date(file.lastModified||Date.now()).toISOString()});await uEnsureEmployeeTasks(true);toast("Datei sicher hochgeladen.","success")}

async function uEnablePush(){if(S.u.push.busy)return;S.u.push.busy=true;try{if(!("serviceWorker"in navigator)||!("PushManager"in window))throw new Error("Web Push wird auf diesem Gerät nicht unterstützt.");const permission=await Notification.requestPermission();if(permission!=="granted")throw new Error("Benachrichtigungen wurden nicht erlaubt.");const registration=await navigator.serviceWorker.ready;const key=S.u.flags?.web_push?.config?.vapidPublicKey;if(!key)throw new Error("Push-Konfiguration fehlt.");const bytes=Uint8Array.from(atob(key.replace(/-/g,"+").replace(/_/g,"/").padEnd(Math.ceil(key.length/4)*4,"=")),char=>char.charCodeAt(0));const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});await uCall("pushSubscribe",{subscription:subscription.toJSON(),userAgent:navigator.userAgent});toast("Push-Benachrichtigungen aktiviert.","success")}finally{S.u.push.busy=false}}

function uHasUnsafeWork(){return Boolean(S.busy||document.querySelector(".u-dialog-backdrop")||document.querySelector('input[type="file"]')?.files?.length)}
function uShowUpdate(registration){if(document.querySelector(".u-update-banner"))return;const banner=document.createElement("div");banner.className="u-update-banner";banner.innerHTML='<span>Neue Version verfügbar</span><button type="button">Aktualisieren</button>';banner.querySelector("button").addEventListener("click",()=>{if(uHasUnsafeWork()){toast("Bitte laufende Eingaben oder Uploads zuerst abschließen.","warning");return}registration.waiting?.postMessage({type:"AORA_ACTIVATE_UPDATE"})});document.body.appendChild(banner)}
async function uRegisterWorker(){if(!("serviceWorker"in navigator))return;const query=new URLSearchParams({supabase:CFG.url,kioskFunction:CFG.kioskWorkspaceFunction});const registration=await navigator.serviceWorker.register(`/sw.js?${query}`,{updateViaCache:"none"});if(registration.waiting)uShowUpdate(registration);registration.addEventListener("updatefound",()=>registration.installing?.addEventListener("statechange",()=>{if(registration.waiting&&navigator.serviceWorker.controller)uShowUpdate(registration)}));navigator.serviceWorker.addEventListener("controllerchange",()=>{if(!uHasUnsafeWork())location.reload()})}
window.addEventListener("load",()=>uRegisterWorker().catch(error=>console.warn("Service Worker registration failed",error)));

let uDraggedShift=null;
document.addEventListener("dragstart",event=>{const card=event.target.closest?.("[data-shift-id]");if(card){uDraggedShift=card.dataset.shiftId;event.dataTransfer.effectAllowed="move"}});
document.addEventListener("dragover",event=>{const target=event.target.closest?.("[data-u-drop-date]");if(target){event.preventDefault();target.classList.add("dragover")}});
document.addEventListener("dragleave",event=>event.target.closest?.("[data-u-drop-date]")?.classList.remove("dragover"));
document.addEventListener("drop",async event=>{const target=event.target.closest?.("[data-u-drop-date]");if(!target||!uDraggedShift)return;event.preventDefault();target.classList.remove("dragover");const shift=S.u.schedule.data?.shifts?.find(item=>item.id===uDraggedShift);if(!shift)return;try{await uCall("updateShift",{shift:{...shift,date:target.dataset.uDropDate,employeeId:target.dataset.uDropEmployee||null,status:target.dataset.uDropEmployee?"draft":"open"},expectedVersion:shift.version});await uEnsureSchedule(true)}catch(error){toast(uErrorMessage(error),"error")}finally{uDraggedShift=null}});

document.addEventListener("change",event=>{const input=event.target;if(input.matches?.("[data-u-task-input]"))uSaveTaskInput(input).catch(error=>toast(uErrorMessage(error),"error"));if(input.matches?.("[data-u-task-file]"))uUploadTaskFile(input).catch(error=>toast(uErrorMessage(error),"error"))});
document.addEventListener("click",async event=>{const target=event.target.closest?.("[data-u]");if(!target)return;const action=target.dataset.u;try{
  if(action==="dialog-close"){target.closest(".u-dialog-backdrop")?.remove();return}
  if(action==="employee-tasks"){S.employeeView="tasks";render();return}
  if(action==="calendar-mode"){S.u.calendar.mode=target.dataset.mode;S.u.calendar.data=null;render();return}
  if(action==="calendar-prev"||action==="calendar-next"){const amount=action.endsWith("prev")?-1:1;const cursor=S.u.calendar.cursor||uMonthStart(berlin().date);S.u.calendar.cursor=S.u.calendar.mode==="month"?uMonthStart(uAdd(uMonthEnd(cursor),amount>0?1:-Number(cursor.slice(8,10)))):uAdd(cursor,amount*(S.u.calendar.mode==="week"?7:31));S.u.calendar.data=null;render();return}
  if(action==="calendar-today"){S.u.calendar.cursor=uMonthStart(berlin().date);S.u.calendar.selected=berlin().date;S.u.calendar.data=null;render();return}
  if(action==="calendar-day"){S.u.calendar.selected=target.dataset.date;render();return}
  if(action==="calendar-reload"){await uEnsureCalendar(true);return}
  if(action==="shift-response"){const reason=target.dataset.response==="rejected"?await uAsk("Schicht ablehnen","Begründung"):"";await uCall("respondShift",{shiftId:target.dataset.id,response:target.dataset.response,reason,idempotencyKey:crypto.randomUUID()},true);await uEnsureCalendar(true);return}
  if(action==="shift-swap"){const reason=await uAsk("Schichttausch","Begründung oder Wunsch");await uCall("requestSwap",{shiftId:target.dataset.id,reason,idempotencyKey:crypto.randomUUID()},true);await uEnsureCalendar(true);return}
  if(action==="open-shift-claim"){await uCall("requestOpenShift",{shiftId:target.dataset.id,reason:"Über Mitarbeiterkalender reserviert",idempotencyKey:crypto.randomUUID()});await uEnsureCalendar(true);toast("Reservierungsanfrage gesendet.","success");return}
  if(action==="availability"){const reason=await uAsk("Verfügbarkeit","Hinweis (optional)");await uCall("setAvailability",{date:target.dataset.date,type:"available",locationId:S.session.locationId||uCurrentEmployee()?.locationId,reason},true);toast("Verfügbarkeit gespeichert.","success");return}
  if(action==="task-open"){S.employeeView="tasks";S.u.tasks.selected=target.dataset.id;render();return}
  if(action==="schedule-prev"||action==="schedule-next"){S.u.schedule.week=uAdd(S.u.schedule.week||uStartWeek(berlin().date),action.endsWith("prev")?-7:7);S.u.schedule.data=null;render();return}
  if(action==="schedule-today"){S.u.schedule.week=uStartWeek(berlin().date);S.u.schedule.data=null;render();return}
  if(action==="schedule-reload"){await uEnsureSchedule(true);return}
  if(action==="shift-new"){uShiftDialog();return}
  if(action==="shift-edit"){const shift=S.u.schedule.data?.shifts?.find(item=>item.id===target.dataset.shiftId);if(shift)uShiftDialog(shift);return}
  if(action==="shift-delete"){const reason=await uAsk("Schicht löschen","Grund");const shift=S.u.schedule.data?.shifts?.find(item=>item.id===target.dataset.id);await uCall("deleteShift",{id:target.dataset.id,expectedVersion:shift?.version,reason});document.querySelector(".u-dialog-backdrop")?.remove();await uEnsureSchedule(true);return}
  if(action==="series-new"){uSeriesDialog();return}
  if(action==="schedule-copy"){const source=uScheduleRange().from;const targetWeek=uAdd(source,7);await uCall("copyWeek",{locationId:S.locationId,sourceFrom:source,targetFrom:targetWeek});S.u.schedule.week=targetWeek;await uEnsureSchedule(true);return}
  if(action==="schedule-publish"){await uCall("publishWeek",{locationId:S.locationId,...uScheduleRange()});await uEnsureSchedule(true);toast("Woche veröffentlicht.","success");return}
  if(action==="request-decision"){const reason=target.dataset.decision==="rejected"?await uAsk("Anfrage ablehnen","Begründung"):"";await uCall("decideShiftRequest",{requestId:target.dataset.id,decision:target.dataset.decision,reason,idempotencyKey:crypto.randomUUID()});await uEnsureSchedule(true);return}
  if(action==="task-select"){S.u.tasks.selected=target.dataset.id;render();return}
  if(action==="tasks-reload"){await uEnsureEmployeeTasks(true);return}
  if(action==="task-submit"){await uCall("submitTask",{taskId:target.dataset.id});await uEnsureEmployeeTasks(true);toast("Aufgabe abgeschlossen.","success");return}
  if(action==="task-claim"){await uCall("claimTask",{taskId:target.dataset.id,idempotencyKey:crypto.randomUUID()},true);await uEnsureEmployeeTasks(true);return}
  if(action==="template-new"){uTemplateDialog();return}
  if(action==="template-edit"){uTemplateDialog(S.u.tasks.managerData?.templates?.find(item=>item.id===target.dataset.id));return}
  if(action==="rule-new"){uRuleDialog();return}
  if(action==="manual-task-new"){uManualTaskDialog();return}
  if(action==="task-review"){const reason=target.dataset.decision==="rejected"?await uAsk("Aufgabe zurückweisen","Begründung"):"";await uCall("reviewTask",{taskId:target.dataset.id,decision:target.dataset.decision,reason});await uEnsureManagerTasks(true);return}
  if(action==="push-enable"){await uEnablePush();return}
}catch(error){toast(uErrorMessage(error),"error")}});
